"""Fatai vision module for RetinaPy training stack."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


class Accuracy:
    """Accuracy metric for classification."""

    __name__ = "accuracy"

    def __init__(self):
        self.correct = 0
        self.total = 0

    def __call__(self, preds, targets):
        self.correct += (preds.argmax(dim=1) == targets).sum().item()
        self.total += targets.shape[0]
        return self

    def compute(self):
        return self.correct / self.total if self.total > 0 else 0.0


def accuracy():
    """Return an accuracy metric instance."""
    return Accuracy()


@dataclass
class VisionLearner:
