    Args:
        arch: The backbone architecture name (e.g., 'resnet18')
        n_out: Number of output classes
        metrics: List of metric instances to use

    Returns:
        A VisionLearner instance
    """
    return VisionLearner(arch=arch, n_out=n_out, metrics=metrics)
